/* Nominatim geocoding with rate-limited queue */

const NOMINATIM_BASE = 'https://nominatim.openstreetmap.org/search';
const MIN_INTERVAL_MS = 1100;

let lastRequestAt = 0;
const queue = [];
let processing = false;

function enqueue(task) {
  return new Promise((resolve, reject) => {
    queue.push({ task, resolve, reject });
    pumpQueue();
  });
}

async function pumpQueue() {
  if (processing || !queue.length) return;
  processing = true;
  while (queue.length) {
    const wait = Math.max(0, MIN_INTERVAL_MS - (Date.now() - lastRequestAt));
    if (wait) await new Promise((r) => setTimeout(r, wait));
    const { task, resolve, reject } = queue.shift();
    lastRequestAt = Date.now();
    try {
      resolve(await task());
    } catch (e) {
      reject(e);
    }
  }
  processing = false;
}

async function nominatimSearch(query, limit = 5) {
  const url = `${NOMINATIM_BASE}?format=json&countrycodes=ch&addressdetails=1&limit=${limit}&q=${encodeURIComponent(query)}`;
  const res = await fetch(url, {
    headers: {
      'Accept-Language': 'en',
      'Accept': 'application/json',
      'User-Agent': 'SwissTaxLocator/1.0 (wealth-tools; contact via site owner)',
    },
  });
  if (!res.ok) throw new Error(`Geocoding failed (${res.status})`);
  return res.json();
}

function parseNominatimResult(best) {
  const addr = best.address || {};
  const gemeinde = addr.municipality || addr.city || addr.town ||
    addr.village || addr.hamlet || addr.suburb || addr.county;
  const canton = addr.state;
  return {
    gemeinde,
    canton,
    lat: parseFloat(best.lat),
    lon: parseFloat(best.lon),
    displayName: best.display_name,
    raw: best,
  };
}

/* localStorage registry — up to 200 locations, JSON/CSV import & export */

const STORAGE_KEY = 'swissTaxRegistry';
const MAX_LOCATIONS = 200;
const SCHEMA_VERSION = 2;

function loadRegistry() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return emptyRegistry();
    const data = JSON.parse(raw);
    const entries = Array.isArray(data.entries) ? data.entries : [];
    const migrated = entries.map(normalizeEntry).filter(Boolean).slice(0, MAX_LOCATIONS);
    return {
      version: SCHEMA_VERSION,
      max_locations: MAX_LOCATIONS,
      updated_at: data.updated_at || new Date().toISOString(),
      entries: migrated,
    };
  } catch {
    return emptyRegistry();
  }
}

function emptyRegistry() {
  return {
    version: SCHEMA_VERSION,
    max_locations: MAX_LOCATIONS,
    updated_at: new Date().toISOString(),
    entries: [],
  };
}

function saveRegistry(data) {
  const payload = {
    version: SCHEMA_VERSION,
    max_locations: MAX_LOCATIONS,
    updated_at: new Date().toISOString(),
    entries: data.entries.slice(0, MAX_LOCATIONS),
  };
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
    return { ok: true };
  } catch (err) {
    if (err && (err.name === 'QuotaExceededError' || err.code === 22)) {
      return { ok: false, reason: 'quota' };
    }
    throw err;
  }
}

